#!/usr/bin/env python3
"""Create ZipCrypto-encrypted zips for testing."""
import struct, binascii, sys, zlib

def crc32_tab():
    tab = []
    for i in range(256):
        c = i
        for _ in range(8):
            c = (c >> 1) ^ (0xEDB88320 if c & 1 else 0)
        tab.append(c)
    return tab

TAB = crc32_tab()

def upd(crc, b):
    return ((crc >> 8) ^ TAB[(crc ^ b) & 0xFF]) & 0xFFFFFFFF

class ZipCrypto:
    def __init__(self, password):
        self.k = [0x12345678, 0x23456789, 0x34567890]
        for b in password:
            self.update(b)
    def update(self, b):
        self.k[0] = upd(self.k[0], b)
        self.k[1] = (self.k[1] + (self.k[0] & 0xFF)) & 0xFFFFFFFF
        self.k[1] = (self.k[1] * 134775813 + 1) & 0xFFFFFFFF
        self.k[2] = upd(self.k[2], (self.k[1] >> 24) & 0xFF)
    def decrypt_byte(self):
        t = (self.k[2] | 2) & 0xFFFFFFFF
        return ((t * (t ^ 1)) >> 8) & 0xFF
    def encrypt(self, data):
        out = bytearray()
        for b in data:
            c = b ^ self.decrypt_byte()
            self.update(b)
            out.append(c)
        return bytes(out)

def make_zip(path, password, content=b'hello world\n', name=b'test.txt', method=0):
    if isinstance(password, str): password = password.encode()
    crc = binascii.crc32(content) & 0xFFFFFFFF
    if method == 8:
        comp = zlib.compressobj(9, zlib.DEFLATED, -15)
        cdata = comp.compress(content) + comp.flush()
    else:
        cdata = content
    zc = ZipCrypto(password)
    import random
    random.seed(42)
    header = bytes(random.randrange(256) for _ in range(11)) + bytes([(crc >> 24) & 0xFF])
    enc = zc.encrypt(header + cdata)
    csize = len(enc)
    mtime, mdate = 0, 0x21
    flags = 0x1
    local = struct.pack('<I5H3I2H', 0x04034b50, 20, flags, method, mtime, mdate, crc, csize, len(content), len(name), 0) + name
    cd = struct.pack('<I6H3I5H2I', 0x02014b50, 20, 20, flags, method, mtime, mdate, crc, csize, len(content), len(name), 0, 0, 0, 0, 0, 0) + name
    cdoff = len(local) + csize
    eocd = struct.pack('<I4H2IH', 0x06054b50, 0, 0, 1, 1, len(cd), cdoff, 0)
    with open(path, 'wb') as f:
        f.write(local + enc + cd + eocd)

if __name__ == '__main__':
    make_zip(sys.argv[1], sys.argv[2], method=int(sys.argv[3]) if len(sys.argv) > 3 else 0)

