                let mut lit_lengths = [0u8; 288];
                for i in 0..144 {
                    lit_lengths[i] = 8;
                }
                for i in 144..256 {
                    lit_lengths[i] = 9;
                }
                for i in 256..280 {
                    lit_lengths[i] = 7;
                }
                for i in 280..288 {
                    lit_lengths[i] = 8;
                }
                let lit = Huffman::new(&lit_lengths)?;
                let dist = Huffman::new(&[5u8; 30])?;
                inflate_block(&mut br, &mut out, &lit, &dist)?;
            }
            2 => {
                let hlit = br.get(5)? as usize + 257;
                let hdist = br.get(5)? as usize + 1;
                let hclen = br.get(4)? as usize + 4;
                if hlit > 288 || hdist > 30 {
