        }
    }
}

fn inflate_block(
    br: &mut BitReader,
    out: &mut Vec<u8>,
    lit: &Huffman,
    dist: &Huffman,
) -> Option<()> {
    loop {
        let sym = lit.decode(br)?;
        if sym < 256 {
            out.push(sym as u8);
        } else if sym == 256 {
            return Some(());
        } else {
            let li = (sym - 257) as usize;
            if li >= 29 {
                return None;
            }
            let len = LEN_BASE[li] as usize + br.get(LEN_EXTRA[li] as u32)? as usize;
            let dsym = dist.decode(br)? as usize;
            if dsym >= 30 {
                return None;
            }
            let d = DIST_BASE[dsym] as usize + br.get(DIST_EXTRA[dsym] as u32)? as usize;
            if d > out.len() {
                return None;
            }
            let start = out.len() - d;
            for k in 0..len {
                let b = out[start + k];
                out.push(b);
            }
        }
    }
}

