// Traditional PKWARE ZipCrypto cipher.

const fn make_table() -> [u32; 256] {
    let mut table = [0u32; 256];
    let mut i = 0;
    while i < 256 {
        let mut c = i as u32;
        let mut k = 0;
        while k < 8 {
            c = if c & 1 != 0 { 0xEDB88320 ^ (c >> 1) } else { c >> 1 };
            k += 1;
        }
        table[i] = c;
        i += 1;
    }
    table
}

static TABLE: [u32; 256] = make_table();

fn crc32_update(crc: u32, b: u8) -> u32 {
    TABLE[((crc ^ b as u32) & 0xFF) as usize] ^ (crc >> 8)
}

pub struct ZipCrypto {
    keys: [u32; 3],
}

impl ZipCrypto {
    pub fn new(password: &[u8]) -> Self {
        let mut z = ZipCrypto {
            keys: [0x12345678, 0x23456789, 0x34567890],
        };
        for &b in password {
            z.update(b);
        }
        z
    }

    fn update(&mut self, b: u8) {
        self.keys[0] = crc32_update(self.keys[0], b);
        self.keys[1] = self
            .keys[1]
            .wrapping_add(self.keys[0] & 0xFF)
            .wrapping_mul(134775813)
            .wrapping_add(1);
        self.keys[2] = crc32_update(self.keys[2], (self.keys[1] >> 24) as u8);
    }

    fn decrypt_byte(&self) -> u8 {
        let t = self.keys[2] | 2;
        ((t.wrapping_mul(t ^ 1)) >> 8) as u8
    }

    // Decrypt one byte, advancing the keys with the plaintext byte.
    pub fn decrypt(&mut self, cipher: u8) -> u8 {
        let plain = cipher ^ self.decrypt_byte();
        self.update(plain);
        plain
    }

    pub fn decrypt_slice(&mut self, data: &[u8]) -> Vec<u8> {
        let mut out = Vec::with_capacity(data.len());
        for &c in data {
            out.push(self.decrypt(c));
        }
        out
    }
}

