// Minimal ZIP archive reader: EOCD scan, central directory parsing,
// and password verification for ZipCrypto and WinZip AES entries.

use crate::crc32::crc32;
use crate::inflate::inflate;
use crate::sha1::pbkdf2_hmac_sha1;
use crate::zipcrypto::ZipCrypto;

pub enum ZipError {
    Invalid(&'static str),
    Unsupported(&'static str),
    Io(std::io::Error),
}

impl std::fmt::Display for ZipError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ZipError::Invalid(m) => write!(f, "invalid Zip archive: {}", m),
            ZipError::Unsupported(m) => write!(f, "unsupported Zip archive: {}", m),
            ZipError::Io(e) => write!(f, "{}", e),
        }
    }
}

pub struct AesInfo {
    pub strength: u8, // 1 = AES-128, 2 = AES-192, 3 = AES-256
    pub method: u16,  // actual compression method
}

pub struct Entry {
    pub name: Vec<u8>,
    pub flags: u16,
    pub method: u16,
    pub mtime: u16,
    pub crc: u32,
    pub csize: u64,
    pub local_offset: u64,
    pub aes: Option<AesInfo>,
}

impl Entry {
    pub fn encrypted(&self) -> bool {
        self.flags & 0x1 != 0
    }
}

fn u16_at(b: &[u8], off: usize) -> Option<u16> {
    Some(u16::from_le_bytes([*b.get(off)?, *b.get(off + 1)?]))
}

fn u32_at(b: &[u8], off: usize) -> Option<u32> {
    Some(u32::from_le_bytes([
        *b.get(off)?,
        *b.get(off + 1)?,
        *b.get(off + 2)?,
        *b.get(off + 3)?,
    ]))
}

pub struct Archive {
    pub data: Vec<u8>,
    pub entries: Vec<Entry>,
}

pub fn open(path: &str) -> Result<Archive, ZipError> {
    let data = std::fs::read(path).map_err(ZipError::Io)?;
    parse(data)
}

pub fn parse(data: Vec<u8>) -> Result<Archive, ZipError> {
    // Locate the End Of Central Directory record.
    let len = data.len();
    let max_back = 22 + 65535;
    let window_start = len.saturating_sub(max_back);
    let mut eocd = None;
    if len >= 4 {
        let mut i = len - 4;
        loop {
            if &data[i..i + 4] == b"PK\x05\x06" {
                eocd = Some(i);
                break;
            }
            if i == window_start {
                break;
            }
            i -= 1;
        }
    }
    let eocd = eocd.ok_or(ZipError::Invalid("Could not find EOCD"))?;
    // EOCD fixed part is 22 bytes including signature.
    if eocd + 22 > len {
        return Err(ZipError::Invalid("Unexpected end of zip::spec::Zip32CDEBlock"));
    }
    let nentries = u16_at(&data, eocd + 10).unwrap() as usize;
    let cd_size = u32_at(&data, eocd + 12).unwrap() as usize;
    let cd_offset = u32_at(&data, eocd + 16).unwrap() as usize;

    let cd_end = cd_offset.saturating_add(cd_size).min(len);
    let mut entries = Vec::with_capacity(nentries);
    let mut off = cd_offset;
    for _ in 0..nentries {
        if off + 46 > cd_end || &data[off..off + 4] != b"PK\x01\x02" {
            return Err(ZipError::Invalid(
