fn verify_aes(data: &[u8], aes: &AesInfo, password: &[u8]) -> bool {
    let (salt_len, key_len) = match aes.strength {
        1 => (8usize, 16usize),
        2 => (12, 24),
        _ => (16, 32),
    };
