fn verify_zipcrypto(data: &[u8], entry: &Entry, password: &[u8]) -> bool {
    if data.len() < 12 {
        return false;
    }
    let mut cipher = ZipCrypto::new(password);
    let mut check_byte = 0u8;
    for &c in &data[..12] {
        check_byte = cipher.decrypt(c);
